ALTER TABLE public.exercise_programs ADD COLUMN IF NOT EXISTS clinic_id uuid REFERENCES public.clinics(id);
UPDATE public.exercise_programs ep SET clinic_id=a.clinic_id FROM public.assessments a WHERE ep.assessment_id=a.id AND a.clinic_id IS NOT NULL AND ep.clinic_id IS NULL;
CREATE OR REPLACE FUNCTION public.validate_hep_clinic_branding() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.clinic_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.clinic_id IS DISTINCT FROM OLD.clinic_id) AND auth.uid() IS NOT NULL AND NOT public.is_clinic_member(auth.uid(),NEW.clinic_id) AND NOT EXISTS(SELECT 1 FROM public.clinics WHERE id=NEW.clinic_id AND owner_user_id=auth.uid()) THEN RAISE EXCEPTION 'clinic access required'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_hep_clinic_branding BEFORE INSERT OR UPDATE OF clinic_id ON public.exercise_programs FOR EACH ROW EXECUTE FUNCTION public.validate_hep_clinic_branding();
CREATE OR REPLACE FUNCTION public.get_hep_clinic_branding(_token text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('clinic_name',c.name,'clinic_logo_url',c.logo_url,'clinic_brand_color',c.brand_color) FROM public.exercise_programs ep LEFT JOIN public.assessments a ON a.id=ep.assessment_id JOIN public.clinics c ON c.id=COALESCE(ep.clinic_id,a.clinic_id) WHERE ep.token=_token AND length(_token)>=16 AND ep.expires_at>now() LIMIT 1; $$;
REVOKE ALL ON FUNCTION public.get_hep_clinic_branding(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_hep_clinic_branding(text) TO anon,authenticated,service_role;